export type SocialIconName = 'facebook' | 'instagram' | 'pinterest';

/** Pulls one glyph out of {@link SocialIconsSprite}. */
export function SocialIcon({
  name,
  ...props
}: { name: SocialIconName } & React.SVGProps<SVGSVGElement>) {
  return (
    <svg viewBox="0 0 64 64" aria-hidden="true" {...props}>
      <use href={`#${name}-icon`} />
    </svg>
  );
}
